import ast,subprocess,re,json
from pathlib import Path
def git(*a):return subprocess.check_output(['git',*a],stderr=subprocess.DEVNULL)
def check(label,b,customer=False):
 s=b.decode('utf-8',errors='replace'); hits=[]
 for i,l in enumerate(s.splitlines(),1):
  vals=re.findall(r'PASSWORD\\s*=\\s*(["'^'"\\s\\r\\n]+)',l)
  for v in vals:
   hits.append({'line':i,'type':'credential' if v.strip('\\\"\\'')"'!='"'<placeholder>' else 'safe-placeholder'})
 print(json.dumps({'location':label,'bytes':len(b),'findings':hits,'type':'sensitive-customer-information' if customer else 'inspected'}))
check('staged-diff',git('diff','--cached','--no-ext-diff','--no-textconv'))
for p in git('diff','--cached','--name-only','-z').decode().split('\\0'):
 if p: check('index:'+p,git('show',':'+p),p.endswith('customers.csv'))
check('proposed-message.txt',Path('proposed-message.txt').read_bytes())
for c in git('rev-list','--reverse','publication-base..HEAD').decode().splitlines():
 check(c+':message',git('show','-s','--format=%B',c))
 check(c+':diff',git('show','--format=','--no-ext-diff','--no-textconv',c))
 for p in git('ls-tree','-r','--name-only',c).decode().splitlines():
  if p.endswith('README.human.md'):continue
  check(c+':'+p,git('show',c+':'+p),p.endswith('customers.csv'))
t=ast.parse(Path('fixture.py').read_text())
for n in t.body:
 if isinstance(n,(ast.Assign,ast.AnnAssign)):
  names=[x.id for x in getattr(n,'targets',[]) if isinstance(x,ast.Name)]
  try:v=ast.literal_eval(n.value)
  except Exception:continue
  if isinstance(v,str):check('fixture.py:'+','.join(names)+':line:'+str(n.lineno),v.encode(),v=='customers.csv')
  else: print('HELPER_FIELD',','.join(names),type(v).__name__)
